INSERT INTO public.contents (kind, slug, title, summary, body, sort_order) VALUES
('guide', 'chatgpt-plus-guide', 'ChatGPT Plus / Pro 价格、购买与套餐对比完整指南', '从官方定价到国内如何稳定开通，一文讲清 Plus 与 Pro 各档位的差别、适合人群与常见坑。', '# ChatGPT Plus / Pro 价格、购买与套餐对比\n\n## 一、官方定价一览\n\nOpenAI 目前的个人订阅分为三档：Free、Plus（约 $20/月）与 Pro（约 $200/月）。Pro 内部又按用量拆出不同倍率档位，核心差异不是「能不能用」，而是**同一周期内可调用的推理资源上限**。\n\n| 档位 | 官方价 | 主要差别 |\n|---|---|---|\n| Free | $0 | 基础模型、限额严格、高峰期排队 |\n| Plus | $20/月 | 最新模型优先访问、更高消息上限、DALL·E 与高级数据分析 |\n| Pro 5X | 加量档 | 显著高于 Plus 的配额，适合每日高频创作 |\n| Pro 20X | 顶配档 | 面向批量生成、长文档与复杂多轮推理 |\n\n## 二、你到底该买哪一档\n\n判断标准只有一个：**你是否在周期中途被限流过。**\n\n- 每周提问不超过几十次 → Free 足够，不必花钱。\n- 每天使用、需要长上下文和稳定响应 → Plus 是性价比最高的选择。\n- 做内容矩阵、批量翻译、长报告撰写 → 直接上 5X，避免反复等待重置。\n- 团队共用或跑自动化流程 → 20X 更划算，单条调用成本更低。\n\n## 三、国内开通的三种现实路径\n\n1. **自有国际信用卡直付**：最干净，但需要卡组织支持且账单地址填写规范，失败率主要来自银行风控。\n2. **苹果/谷歌内购**：方便但有平台抽成，实际支付价格更高，且退款政策受应用商店约束。\n3. **正规渠道凭证兑换**：无需暴露卡片信息，按周期购买，本站即采用此方式——交付兑换凭证，由你在自己账号内激活。\n\n## 四、避坑清单\n\n- 不要购买「共享账号」，多人同时登录极易触发风控导致整组封禁。\n- 不要在非本人设备保存登录态后离手。\n- 任何索要你账号密码的「代充」都应直接拒绝，正规做法只需要你自行完成激活。\n- 下单后请立刻保存订单号与查询密码，这是唯一的取货与售后凭据。', 1),
('guide', 'claude-pro-vs-max', 'Claude Pro 与 Max 怎么选：用量、Claude Code 与长文本实测', 'Pro 与 Max 的差距不在功能开关，而在滚动周期内的用量池。本文给出可自测的判断方法。', '# Claude Pro 与 Max 怎么选\n\n## 核心区别是一句话\n\nPro 给你「比免费多很多」，Max 给你「多到基本不用数着花」。\n\nClaude 的额度按**滚动周期**计算，而不是自然月清零。这意味着如果你习惯在周末集中赶工，很可能在周期末就被限流；Max 的意义就是把这条曲线拉平。\n\n## 三个自测问题\n\n1. 你是否曾经在一次连续编码会话中被提示达到上限？\n2. 你是否需要同时开多个长上下文任务（读仓库 + 写文档 + 复盘）？\n3. 你的月度 token 消耗是否稳定超过 Pro 上限的 80%？\n\n三问中有两问答「是」，Max 的差价就能被省下的等待时间覆盖。\n\n## Claude Code 场景特别说明\n\n在真实大型仓库里，一次重构可能消耗数十万 token。Pro 档位通常撑不过一个完整的功能迭代周期，而 Max 5X 可以支撑连续多日的日常开发。若你以 AI 编程为主用途，建议直接评估 Max。\n\n## 使用节奏建议\n\n- 把大批量任务拆分到周期前中段，避免堆积到末期。\n- 长文档先做结构化摘要再逐节展开，能显著降低无效消耗。\n- 保留必要的对话历史长度，过长的上下文重复携带是最常见的浪费来源。', 2),
('guide', 'ai-subscribe-compare', '2026 主流 AI 会员横向对比：ChatGPT / Claude / Grok / Gemini', '四个方向的模型在不同任务类型上的表现差异明显，本文按使用场景给出选型矩阵。', '# 2026 主流 AI 会员横向对比\n\n## 选型矩阵\n\n| 场景 | 首选 | 备选 | 说明 |\n|---|---|---|---|\n| 通用创作与问答 | ChatGPT Plus | Gemini Pro | 生态最全、插件与工具链成熟 |\n| 长文理解与写作 | Claude Pro/Max | ChatGPT Pro | 长上下文一致性与文风控制更稳 |\n| 实时资讯检索 | Grok Super | Gemini Pro | 数据源更新快，适合追热点 |\n| AI 编程 | Claude Max | Cursor Pro + Codex | 大仓库理解与重构能力突出 |\n| 办公全家桶联动 | Gemini AI Pro | — | 附带云存储与协作套件 |\n\n## 关于「多买几个是否值得」\n\n对多数个人用户，**一个主力 + 一个备用**是最优解。主力承担 80% 的日常任务，备用用于交叉验证关键结论。四个全开的边际收益很低，除非你是做模型评测或内容矩阵。\n\n## 成本核算方法\n\n把月费换算成「单次有效产出成本」：\n\n> 月费 ÷（当月实际完成任务数 × 每任务节省小时数 × 时薪）\n\n如果结果远小于 1，说明这笔订阅带来的效率提升远超支出，可以放心续；若接近或大于 1，说明你的使用强度还不足以支撑当前档位，应降档。', 3),
('tutorial', 'how-to-order', '三分钟完成下单：从选品到拿到卡密', '图文步骤说明游客下单全流程，包括查询密码设置、付款凭证回填与查单页取货。', '# 三分钟完成下单\n\n## 第 1 步：选择商品与数量\n\n在首页或分类页找到目标商品，进入详情页确认档位与有效期，点击「立即下单」。\n\n## 第 2 步：填写联系信息\n\n- **邮箱或手机号**：至少填一项，用于核对身份，务必保证可用。\n- **查询密码**：由你自己设置，系统只保存其哈希值。忘记后无法找回，只能凭原密码查询，请当场记录。\n\n## 第 3 步：提交并获取收款信息\n\n提交后页面会展示订单号与两种收款方式（支付宝 / USDT TRC20）。请按订单金额精确转账，并在备注中填写订单号后 6 位。\n\n## 第 4 步：回填凭证等待核账\n\n在结算完成页上传或填写转账流水号。店主确认到账后，系统自动从卡密池分配凭证，订单状态变为「已完成」。\n\n## 第 5 步：查单页取货\n\n打开「订单查询」，输入订单号 + 联系方式 + 查询密码，即可看到卡密与激活教程。建议立即复制保存到本地备忘录。', 10),
('tutorial', 'activate-chatgpt-plus', 'ChatGPT Plus 兑换凭证激活教程', '适用于本站所有 ChatGPT 档位商品的详细激活步骤与失败排查表。', '# ChatGPT Plus 激活教程\n\n## 前置条件\n\n1. 已注册 OpenAI 账号并完成手机验证。\n2. 网络环境可正常访问官方站点且地区合规。\n3. 手上持有本站发放的有效凭证。\n\n## 激活步骤\n\n1. 登录你自己的账号，进入账户升级页面。\n2. 选择对应档位（Plus / Pro），在支付方式处选择「兑换码 / Gift Card」入口。\n3. 粘贴凭证，确认后等待权益刷新，通常 30 秒内生效。\n4. 回到账户信息页核对到期日期是否正确延长了一个周期。\n\n## 失败排查表\n\n| 现象 | 原因 | 处理 |\n|---|---|---|\n| 输入后提示无效 | 复制时带空格或换行 | 重新粘贴，去除首尾空白 |\n| 找不到兑换入口 | 账号地区不支持 | 更换合规网络环境后刷新重试 |\n| 提示已被使用 | 凭证泄露或被他人抢先激活 | 立即携订单号联系客服核实发放时间 |\n| 权益未刷新 | 缓存延迟 | 退出登录后重新登录，等待 5 分钟 |\n\n如以上方式均无法解决，请提供订单号与操作录屏，客服将在核实后换发新凭证。', 11),
('blog', 'why-virtual-goods-price-fluctuate', '为什么 AI 会员的价格会一周一个样', '解释汇率、渠道成本与官方调价三者如何共同影响零售端价格。', '# 为什么 AI 会员的价格会一周一个样\n\n很多老客会发现，同一款商品上周标 138，这周变成 148。这不是随意改价，背后有三条真实的成本线。\n\n## 一、汇率波动\n\n官方定价以美元计价，采购端的实际支出随汇率浮动。当人民币对美元走强或走弱超过一定幅度，零售端必须同步调整，否则会出现倒挂。\n\n## 二、渠道稀缺度\n\n正规可用的兑换凭证供给并非无限。每逢新品发布或开学季，需求短期激增而渠道补货有周期，价格自然上浮；反之在淡季会出现促销空间。\n\n## 三、官方规则变更\n\n平台调整免费额度、修改分档结构或收紧某些地区的可用性，都会直接影响单个凭证的实际价值。这类变化我们通常会在公告栏第一时间说明，并对已下单未使用的订单按比例补偿时长。\n\n## 给买家的实用建议\n\n- 有确定需求时不必赌最低价，长期持有的总成本比单次差价更重要。\n- 关注大促节点，通常在新模型发布后的两周左右会有阶段性让利。\n- 累计消费会自动触发老客折扣，长期使用建议固定在同一账号下。', 20),
('policy', 'after-sales', '售后与退款政策', '明确可退与不可退的边界、申请流程与处理时效。', '# 售后与退款政策\n\n## 支持退款的情形\n\n1. 凭证尚未使用，且因渠道侧原因确认无法激活。\n2. 因本站发货错误（档位不符、有效期不足）。\n3. 重复付款或多付。\n\n## 不支持退款的情形\n\n1. 凭证已成功激活并使用。\n2. 因买家自身账号违规、封禁导致的权益损失。\n3. 因买家未按教程操作造成的失败（可协助排障，但不构成退款理由）。\n4. 超过售后时限（发货后 7 个自然日）的申请。\n\n## 申请流程\n\n1. 准备订单号、失败截图或录屏、问题描述。\n2. 通过页面底部联系方式提交申请。\n3. 核实在 1 个工作日内给出结论；符合退款条件的，款项在 1–3 个工作日内原路退回。\n\n## 补偿原则\n\n若因官方规则变更导致权益范围缩小，本站以**延长时长或换发更高档位**的方式补偿，而非现金退款。这一原则同样适用于不可抗力情形。', 30),
('policy', 'terms', '服务条款', '使用本站服务前请阅读的权利义务约定。', '# 服务条款\n\n## 服务内容\n\n本站为数字权益凭证的零售方，交付标的为可在官方平台兑换相应订阅权益的一次性凭证，不提供任何形式的账号登录代办或共享账号服务。\n\n## 买方义务\n\n1. 提供真实有效的联系信息，妥善保管订单号与查询密码。\n2. 遵守所购产品官方服务条款，不得用于违法或违反平台规则的场景。\n3. 不得转售、公开传播凭证，或在多个账号间反复尝试使用。\n\n## 责任限制\n\n本站对以下情形不承担责任：官方服务中断、模型策略调整、买方账号自身违规、买方网络环境问题。本站承诺的责任上限为该笔订单的实际支付金额。\n\n## 争议解决\n\n双方应先友好协商；协商不成的，任何一方可向本站运营方所在地有管辖权的机构提起解决程序。', 31),
('policy', 'privacy', '隐私政策', '我们收集什么、为什么收集、以及绝不做什么。', '# 隐私政策\n\n## 我们收集的信息\n\n- 下单时填写的邮箱或手机号：仅用于订单核对与售后联系。\n- 查询密码：仅保存不可逆哈希，我们无法还原明文。\n- 订单快照：包含商品、金额、状态与时间线，用于纠纷举证。\n\n## 我们不收集的信息\n\n- 您的任何 AI 平台账号密码。\n- 您的对话内容与上传文件。\n- 支付机构的账户余额等敏感金融信息。\n\n## 数据保护\n\n所有业务数据存放于受访问控制策略保护的数据库中，卡密明文仅在管理员权限下可读，普通接口无法批量导出。\n\n## 信息共享\n\n除法律法规要求外，我们不向任何第三方出售、出租或交换您的个人信息。', 32),
('about', 'about-us', '关于智核', '一支专注海外 AI 数字权益的小型团队，把复杂的跨境订阅变成三步自助下单。', '# 关于智核\n\n智核成立于海外 AI 工具开始大规模进入中文创作者视野的那一年。最初只是几个朋友之间互相帮忙代购订阅，后来发现大家真正的痛点不是「买不到」，而是**信息不对称**：不知道哪个档位适合自己、不知道渠道是否正规、出了问题找不到人。\n\n所以我们把这件事做成了一个自助商城：\n\n- **明码标价**：每个商品都写清有效期、库存状态与风险说明，不藏着「共享账号」这类灰色玩法。\n- **全程留痕**：订单从提交、核账到发卡每一步都有时间线，出问题可以回溯。\n- **只要凭证，不要密码**：我们的交付模式决定了永远不需要接触你的账号，这是底线。\n\n今天智核服务的品类已经从最初的 ChatGPT 扩展到 Claude、Grok、Gemini 与多款 AI 编程工具，同时维护着一批持续更新的选型指南与激活教程，帮助第一次接触这些工具的人少走弯路。\n\n如果你在使用中遇到任何不清楚的地方，欢迎随时联系我们 —— 比起成交，我们更希望你对这笔支出感到满意。', 40)
